/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit, ViewChild } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { GResponse } from '../../../../core/common/GResponse';
import { Urls } from '../../../../core/common/Urls';
import { G } from '../../../../core/common/G';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { IonContent, AlertController, LoadingController, ToastController } from '@ionic/angular';
import { GAccount } from '../../../../core/common/GAccount';
import { CourseService } from '../../../../data/service/course/course.service';
import { SliderService } from '../../../../data/service/site/Slider.service';
import { BleService } from 'src/app/data/service/Ble/Ble.service';

@Component({
  selector: 'app-dbw',
  templateUrl: './dbw.component.html',
  styleUrls: ['./dbw.component.scss']
})
export class DbwComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  tunerPlusVideo: string | SafeUrl = 'zYFuN';

  form: FormGroup;
  form2: FormGroup;
  dwell = 3.45;
  H = 0.006576;
  mH = 6.58;
  u = 3.14159 * 4 * Math.pow(10, -7);
  received = '';

  constructor(
    public ble: BleService,
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService
  ) {
    this.ble.data$.subscribe(v => this.received = v);
    this.isShow = false;
    if (!GAccount.IsLoggedIn()) {
      this.router.navigateByUrl('/Account');
    }
    this.check();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(4).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.tunerPlusVideo = G.TunerPlusDwellVideo;

    this.form = this.fb.group({
      R: [0.4, [Validators.required, Validators.min(0), Validators.max(100000)]],
      I: [6.18, [Validators.required, Validators.min(0), Validators.max(1000)]],
      A: [6, [Validators.required, Validators.min(0), Validators.max(1000)]]
    });

    this.form2 = this.fb.group({
      N: [10000, [Validators.required, Validators.min(0), Validators.max(100000)]],
      Area: [0.000314, [Validators.required, Validators.min(0), Validators.max(1000)]],
      L: [6, [Validators.required, Validators.min(0), Validators.max(1000)]]
    });
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  scan() {
    this.ble.scanAndConnect();
  }

  send() {
    this.ble.send('TEST123\n');
  }

  disconnect() {
    this.ble.disconnect();
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc2() {

    if (!this.form2.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          this.H = +(this.u * Math.pow(this.form2.value.N, 2) * this.form2.value.Area / this.form2.value.L).toFixed(6);
          this.mH = +(this.H * 1000).toFixed(2);

          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          const resist = Math.round(this.form.value.R * 100) / 100;
          const induct = Math.round(this.form.value.I * 100) / 100;
          const current = Math.round(this.form.value.A * 100) / 100;
          this.dwell = Math.round(this.Dwell(resist, induct, current) * 100) / 100;
          this.form.setValue({
            R: resist,
            I: induct,
            A: current
          });
          SharedIonic.dismissLoading(this.loadingController);

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  Dwell(resist, induct, current) {
    const calc_dwell = Math.log(1 - (resist * current / 12)) * (-1 * (induct / resist));
    return calc_dwell;
  }

  onReset2() {

    this.H = 0.006576;
    this.mH = 6.58;
    this.form2.setValue({
      N: 10000,
      Area: 0.000314,
      L: 6
    });
  }

  onReset() {

    this.dwell = 3.45;
    this.form.setValue({
      R: 0.4,
      I: 6.18,
      A: 6
    });
  }

  onInfo(type: string) {

    switch (type) {
      case 'R':
        this.presentActiveAlertConfirm('مقاومت سیم پیچ کویل برحسب اهم');
        break;
      case 'I':
        this.presentActiveAlertConfirm('ظرفیت القا مغناطیسی کویل برحسب میلی هانری');
        break;
      case 'A':
        this.presentActiveAlertConfirm('جریان عبوری از کویل برحسب آمپر');
        break;
      case 'N':
        this.presentActiveAlertConfirm('تعداد دور سیم پیچ');
        break;
      case 'Area':
        this.presentActiveAlertConfirm('مساحت هسته داخلی   (\Pi r^{2})  در متر مربع');
        break;
      case 'L':
        this.presentActiveAlertConfirm('طول سیم پیچ در هر متر');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
}
